    if (!c || c.archived_at) throw new RuleError("That code didn\u2019t work. Check it with your partner.");
    if (c.a === uid) throw new RuleError("That\u2019s your own code. Send it to your partner.");
    if (c.b && c.b !== uid) throw new RuleError("This home already has two people.");
    const w = c.world;
